const raw = $input.item.json;
const d = raw.body || raw;

const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (!d.firstName || !d.lastName || !d.workEmail || !emailRegex.test(d.workEmail)) {
  throw new Error('INVALID_SUBMISSION: missing name or invalid email');
}

return { json: {
  timestamp: new Date().toISOString(),
  firstName: d.firstName || '',
  lastName: d.lastName || '',
  whatsappNumber: d.whatsappNumber || '',
  workEmail: d.workEmail || '',
  companyName: d.companyName || '',
  productCategory: d.productCategory || '',
  webinarTitle: d.webinarTitle || '',
  webinarDatetime: d.webinarDatetime || '',
  webinarJoinUrl: d.webinarJoinUrl || ''
}};
